package com.nexamart.backend.domain;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="delivery_partner_profiles") public class DeliveryPartnerProfile{@Id private Long userId;@OneToOne @MapsId @JoinColumn(name="user_id")private UserAccount user;private String verificationStatus="PENDING";private String vehicleType;private String vehicleNumber;private String licenseReference;private boolean available=false;private Instant updatedAt=Instant.now();public Long getUserId(){return userId;}public UserAccount getUser(){return user;}public void setUser(UserAccount v){user=v;}public String getVerificationStatus(){return verificationStatus;}public void setVerificationStatus(String v){verificationStatus=v;}public String getVehicleType(){return vehicleType;}public void setVehicleType(String v){vehicleType=v;}public String getVehicleNumber(){return vehicleNumber;}public void setVehicleNumber(String v){vehicleNumber=v;}public String getLicenseReference(){return licenseReference;}public void setLicenseReference(String v){licenseReference=v;}public boolean isAvailable(){return available;}public void setAvailable(boolean v){available=v;updatedAt=Instant.now();}public Instant getUpdatedAt(){return updatedAt;}}
